 async function openActivity(change:HouseholdChange){
  const target=await loadActivityTarget(householdId,change);
  if(currentHousehold.current!==householdId)return;
  // Refresh lists before revealing their target, so an update isn't opened in
  // a stale list. Detail dialogs receive a freshly read, household-scoped row.
  if(change.entity_kind==='grocery'||change.entity_kind==='task'||change.entity_kind==='profile')await refresh(true);
  if(currentHousehold.current!==householdId)return;
  activity.close();setPersonFilter('all');setQuery('');setFilter('All');setStoreFilter('all');setActivityFocus(null);
  const kind=change.entity_kind;
  if(kind==='grocery'||kind==='staple'){
   setTab('Groceries',true);if(target)setActivityFocus({kind,id:change.entity_id});
  }else if(kind==='task'){
   setTab('Reminders');if(target?.kind==='task'){setTaskView(reminderIsDone(target.value,today)?'done':'todo');setReminderEditor({item:target.value})}
  }else if(kind==='event'){
   setTab('Calendar');if(target?.kind==='event')setEventDetails(target.value);
  }else if(kind==='note'){
   setTab('Notes');if(target?.kind==='note')openNote(target.value,false);
  }else if(kind==='meal_plan'||kind==='meal_recipe'){
   setTab('Meals');if(target?.kind==='meal_plan')openMeal({kind:'plan',plan:target.value,date:target.value.meal_date,opener:null});
   else if(target?.kind==='meal_recipe')openMeal({kind:'recipe',recipe:target.value,opener:null});
  }else if(kind==='profile'){setSettingsEntry({page:'household'});setModal('settings')}
  if(!target)setToast('This was removed. Showing the shared section instead.');
  window.scrollTo({top:0});
 }
